const RELEASE='lolm-qira-docs-20261118-r1';
export default {async fetch(request,env){
  const u=new URL(request.url),path=u.pathname,body=FILES[path];
  if(body===undefined)return new Response('Not Found',{status:404,headers:{'cache-control':'no-store'}});
  const target=new URL('https://lolm.imagineqira.com'+u.pathname+u.search);
  const headers=new Headers(request.headers);headers.delete('host');
  const origin=()=>env.LOLM_ORIGIN.fetch(new Request(target.toString(),{method:request.method,headers,body:['GET','HEAD'].includes(request.method)?undefined:request.body,redirect:'manual'}));
  if(request.method!=='GET'&&request.method!=='HEAD')return origin();
  if(path.endsWith('.css')||path.endsWith('.js')){
    const mime=path.endsWith('.css')?'text/css; charset=utf-8':'application/javascript; charset=utf-8';
    const h={'content-type':mime,'x-content-type-options':'nosniff','cache-control':path==='/sw.js'?'no-cache, must-revalidate':'public, max-age=300, must-revalidate','x-qira-lolm-release':RELEASE};
    return new Response(request.method==='HEAD'?null:body,{status:200,headers:h});
  }
  let original;try{original=await origin()}catch{return new Response('LOLM public documentation temporarily unavailable',{status:503,headers:{'cache-control':'no-store'}})}
  if(!original.ok||!original.headers.get('content-type')?.includes('text/html'))return original;
  const h=new Headers(original.headers);h.delete('content-length');h.delete('content-encoding');h.set('cache-control','private, no-store');h.set('x-qira-lolm-release',RELEASE);
  return new Response(request.method==='HEAD'?null:body,{status:original.status,headers:h});
}};